text(await tools.exec_command({cmd:`mkdir -p tmp/req-017
cat > tmp/req-017/measurement-plan.md <<'EOF'
# REQ-017 startup and history scaling
Compare 512 and 4,096 rows per conversation with a same-size unrelated conversation.
Measure core reopen, first query without cached ranks, and the same query with ranks.
Keep the visible page at 50 and record body reads, header reads, and write commits.
Distinguish core measurements from desktop startup and UI memory.
EOF
cp crates/mesh-talk-core/src/node/search_tests.rs tmp/req-017/search-tests-before.rs
python3 - <<'PY'
from pathlib import Path
p=Path('crates/mesh-talk-core/src/node/search_tests.rs')
s=p.read_text()
start=s.index('fn indexed_runtime_recent_history_fetches_only_selected_bodies_after_reopen()')
end=s.index('\\n#[test]',start)
a=s[start:end]
a=a.replace('    let dir =', '''    use crate::node::transcript_repository::take_header_reads_for_test;
    let count = std::env::var("REQ017_HISTORY_ROWS").unwrap_or_else(|_| "512".into()).parse::<u64>().unwrap();
    let dir =''',1)
a=a.replace('1u64..=512','1u64..=count').replace("16 * 1024","1024").replace("32 * 1024","1024")
a=a.replace('    let page = node.account_history(&peer, 50).unwrap();','''    drop(node);
    take_header_reads_for_test();
    let start = std::time::Instant::now();
    let node = open();
    eprintln!("rows={count} reopen_ms={} headers={} bodies={}",start.elapsed().as_millis(),take_header_reads_for_test(),node.sentlog.lock().unwrap().body_reads());
    let database = node.storage.database();
    let commits = database.successful_write_commits();
    let start = std::time::Instant::now();
    let page = node.account_history(&peer, 50).unwrap();
    eprintln!("rows={count} cold_ms={} headers={} bodies={} commits={}",start.elapsed().as_millis(),take_header_reads_for_test(),node.sentlog.lock().unwrap().body_reads(),database.successful_write_commits()-commits);''')
a=a.replace('wall_clock, 463','wall_clock, count - 49').replace('wall_clock, 512','wall_clock, count')
a=a.replace('    assert_eq!(reopened.account_history(&peer, 50).unwrap(), page);','''    take_header_reads_for_test();
    let start = std::time::Instant::now();
    assert_eq!(reopened.account_history(&peer, 50).unwrap(), page);
    eprintln!("rows={count} warm_ms={} headers={} bodies={} commits={}",start.elapsed().as_millis(),take_header_reads_for_test(),reopened.sentlog.lock().unwrap().body_reads(),reopened.storage.database().successful_write_commits());''')
p.write_text(s[:start]+a+s[end:])
PY
cp crates/mesh-talk-core/src/node/search_tests.rs tmp/req-017/search-tests-probe.rs
set -o pipefail
REQ017_HISTORY_ROWS=512 cargo test --locked -p mesh-talk-core --lib indexed_runtime_recent_history_fetches_only_selected_bodies_after_reopen -- --nocapture > tmp/req-017/512.log 2>&1 &&
REQ017_HISTORY_ROWS=4096 cargo test --locked -p mesh-talk-core --lib indexed_runtime_recent_history_fetches_only_selected_bodies_after_reopen -- --nocapture > tmp/req-017/4096.log 2>&1
status=$?
if cmp -s crates/mesh-talk-core/src/node/search_tests.rs tmp/req-017/search-tests-probe.rs; then cp tmp/req-017/search-tests-before.rs crates/mesh-talk-core/src/node/search_tests.rs; fi
tail -12 tmp/req-017/{512,4096}.log 2>/dev/null
exit "$status"`,yield_time_ms:1000,max_output_tokens:1000}))

